design.custom_css:
/* ---- first screen -------------------------------------------------------------------------------
   The brief's two reference sites both lead with a big saturated colour field and a phone number you
   cannot miss. The hero band carries the client's own taxi yellow (section bg: accent, dark ink), and
   the rules below make the call button display size and bring the ordering form up into the fold. */

/* The home split hero's photo is forced to a 4:4.6 portrait by the theme (finish.css:102), which made
   the hero 1045px tall and pushed the lead form ~50px below a 900px fold. This client's hero is
   landscape, so the text, both buttons and the form card all fit the first screen. Scoped to this
   site only; the theme-level fix is not approved. */
html body:not(.zs-p-signature).zs-hv-split .zs-hero--home .zs-hero__media .zs-hero__img img { aspect-ratio: 4 / 2.9; }
/* the theme offsets the photo with a taxi-yellow block, which is invisible on a yellow hero: make it
   the brand green so the photo keeps its offset corner. */
html body:not(.zs-p-signature).zs-hv-split .zs-hero--home .e-con.zs-hero__media::before { background: var(--c-primary); }

@media (min-width: 1025px) {
  /* "כפתור חיוג בולט": the hero's call button at display size, not body text. */
  html body .zs-hero--home .zs-btns .zs-b-tel .elementor-button {
    font-size: 1.6rem; font-weight: 800; letter-spacing: .01em; padding: .62em 1.15em; gap: .5em;
  }
  html body .zs-hero--home .zs-btns .zs-b-tel .elementor-button :is(svg, i) { width: 1.1em; height: 1.1em; font-size: 1.1em; }
  html body .zs-hero--home .zs-btns .zs-b-ghost .elementor-button { font-size: 1.1rem; padding: .85em 1.4em; }

  /* The header phone is a filled taxi-yellow pill inside the green outline the standard already gives
     it (that outline is what carries the 3:1 control contrast, WCAG 1.4.11: yellow on white is 1.68).
     At 1024px and below the theme turns the control into the standard plain phone icon (qa-rules). */
  html body .zs-header__cta .elementor-button { background: var(--c-accent); color: var(--c-accent-ink); border-color: var(--c-primary); font-weight: 700; }
  html body .zs-header__cta .elementor-button:hover { background: var(--c-primary); color: var(--c-primary-ink); border-color: var(--c-primary); }
}

/* Phones: Zap QA keeps the two hero buttons side by side, one line each (standards.css), so the call
   button is given the larger share of the row instead of being stacked. Side by side at equal width
   the number does not fit 167px and was clipped; at 1.5 of the row it sits on one line and is still
   the dominant control, which is what "כפתור חיוג בולט" has to mean on a phone. */
@media (max-width: 1024px) {
  html body .zs-hero--home .zs-btns > .zs-b-tel { flex: 1.5 1 0; }
  html body .zs-hero--home .zs-btns > .zs-b-ghost { flex: 1 1 0; }
  html body .zs-hero--home .zs-btns .zs-b-tel .elementor-button { font-size: 1.14rem; font-weight: 800; padding-inline: 8px; }
}

/* ---- the engine bug this client has to work around ----------------------------------------------
   wp/theme/zap-base/assets/main.css:347 gives .zs-cta__text a 420px flex-basis, which cannot fit a
   390px screen and does not shrink, so any cta section scrolls the page sideways on a phone
   (measured here: scrollWidth 434 against a 390 viewport). The generic fix belongs in the theme. */
@media (max-width: 600px) {
  html body .elementor .e-con.zs-cta__text { flex-basis: 100%; min-width: 0; }
  html body .elementor .zs-cta .e-con.zs-btns { width: 100%; flex-wrap: wrap; }
}
